                    OutboxEventHandler handler = handlers.get(event.type());
                    if (handler == null) {
                        throw new IllegalStateException("처리할 수 없는 대기열 작업입니다: " + event.type());
                    }
                    handler.handle(event.payload());
                    outboxRepository.delete(event.id());

